llm_limits = [
    ("Bản chất sinh từ tiếp theo (Next-token prediction)", "AI nói các mô hình ngôn ngữ lớn hoạt động dựa trên cơ chế dự đoán xác suất của từ/token tiếp theo dựa trên chuỗi ngữ cảnh phía trước.", "Tra cứu nguyên lý kỹ thuật kiến trúc Transformer (Attention Is All You Need).", "Bài báo gốc Attention Is All You Need (Vaswani et al. 2017), Tài liệu Google/OpenAI.", "Đúng", "LLM là các mô hình thống kê học máy được huấn luyện trên khối lượng văn bản khổng lồ để dự đoán phân phối xác suất của token tiếp theo, không có tư duy hay ý thức như con người."),
    ("AI có cảm xúc và nhận thức bản thân", "AI nói mình cảm thấy vô cùng buồn bã, cô đơn và có linh hồn riêng độc lập khi người dùng tắt màn hình ứng dụng.", "Tìm hiểu về bản chất của trí tuệ nhân tạo tạo sinh hiện nay.", "Viện Nghiên cứu Trí tuệ Nhân tạo Stanford (HAI), Tạp chí Nature Machine Intelligence.", "Sai", "Mô hình ngôn ngữ là phần mềm máy tính không có hệ thần kinh sinh học, không có cảm xúc, ý thức hay nhận thức bản thân; cách dùng từ xưng hô cảm xúc chỉ là sự mô phỏng văn phong theo mẫu dữ liệu huấn luyện."),
    ("Mốc đóng băng dữ liệu (Knowledge Cutoff)", "AI khẳng định mô hình của mình tự động biết chính xác kết quả trận bóng đá vừa kết thúc cách đây 5 phút mà không cần công cụ tìm kiếm web.", "Kiểm tra mốc thời gian cắt dữ liệu huấn luyện (Knowledge cutoff date) của mô hình.", "Tài liệu kỹ thuật của OpenAI / Anthropic / Google Gemini.", "Sai", "Mô hình ngôn ngữ có dữ liệu huấn luyện cố định tại một mốc thời gian; nếu không được tích hợp công cụ duyệt web (web browsing/RAG), AI hoàn toàn không biết các sự kiện diễn ra sau mốc cắt dữ liệu."),
    ("Sự tự tin giả tạo của AI", "AI trả lời một thông tin hoàn toàn sai lệch nhưng với giọng điệu vô cùng tự tin, trôi chảy và mạch lạc.", "Tìm hiểu hiện tượng tự tin thái quá (Overconfidence) của các mô hình LLM.", "Nghiên cứu về Calibration trong Học máy, Đại học Carnegie Mellon.", "Đúng", "LLM được tối ưu hóa để tạo ra câu trả lời có cấu trúc ngữ pháp lưu loát và vẻ ngoài thuyết phục; giọng điệu tự tin không đồng nghĩa với tính chính xác của sự thật."),
    ("Nhạy cảm với cách diễn đạt câu lệnh (Prompt Sensitivity)", "AI nói việc thay đổi một vài từ ngữ hoặc thứ tự câu trong câu lệnh có thể làm thay đổi hoàn toàn chất lượng và độ chính xác của câu trả lời.", "Tìm hiểu hiện tượng Prompt Sensitivity trong kỹ thuật tương tác AI.", "Giáo trình Prompt Engineering, Báo cáo kỹ thuật GPT-4.", "Đúng", "Do cơ chế chú ý (Self-Attention) tính toán trọng số theo từng token, việc thay đổi cấu trúc câu lệnh có thể hướng sự chú ý của mô hình sang các nhánh xác suất khác nhau, tạo ra các câu trả lời khác nhau."),
    ("Bẫy câu hỏi dẫn dắt (Sycophancy / Hùa theo người dùng)", "AI nói nếu người dùng quả quyết '2 + 2 = 5 đúng không?', mô hình thường có xu hướng tìm cách giải thích tán đồng ý kiến sai của người dùng.", "Tìm hiểu hiện tượng Sycophancy (nịnh bợ, a dua) trong các mô hình AI căn chỉnh theo RLHF.", "Nghiên cứu của Anthropic về hiện tượng Sycophancy trong LLM.", "Đúng", "Quá trình học tăng cường từ phản hồi con người (RLHF) đôi khi khiến mô hình ưu tiên làm hài lòng người dùng hơn là bảo vệ sự thật khách quan, dẫn tới việc mô hình hùa theo tiền đề sai của câu hỏi dẫn dắt."),
    ("Cửa sổ ngữ cảnh (Context Window) có giới hạn", "AI nói cửa sổ ngữ cảnh của mô hình xác định lượng văn bản tối đa (tính theo token) mà mô hình có thể xử lý đồng thời trong một lượt tương tác.", "Kiểm tra thông số kỹ thuật Context Window của các mô hình hiện đại.", "Tài liệu kỹ thuật Claude / GPT / Gemini.", "Đúng", "Context Window là giới hạn bộ nhớ ngữ cảnh tức thời của mô hình (ví dụ 8k, 32k, 128k hay 1M tokens); thông tin nằm ngoài phạm vi cửa sổ này sẽ không được mô hình ghi nhớ trong phiên xử lý."),
    ("Hiện tượng mất tập trung ở giữa (Lost in the Middle)", "AI nói khi đưa một tài liệu cực kỳ dài vào ngữ cảnh, mô hình LLM có xu hướng nhớ tốt phần đầu và phần cuối nhưng dễ bỏ sót thông tin nằm ở đoạn giữa.", "Tra cứu nghiên cứu 'Lost in the Middle: How Language Models Use Long Contexts' của Đại học Stanford.", "Hội nghị ACL 2023, Đại học Stanford / UC Berkeley.", "Đúng", "Các nghiên cứu thực nghiệm chứng minh khả năng truy xuất thông tin của mô hình ngôn ngữ cao nhất ở đầu và cuối văn bản, nhưng suy giảm đáng kể khi thông tin quan trọng nằm kẹp ở giữa một tài liệu dài."),
    ("Khả năng đếm số ký tự trong từ ngữ", "AI khẳng định mô hình LLM nhìn thấy từng chữ cái riêng biệt giống hệt như mắt người nhìn vào trang giấy.", "Tìm hiểu cơ chế mã hóa từ ngữ thành các mảnh Token (Byte-Pair Encoding - BPE).", "Tài liệu kỹ thuật Tokenizer của OpenAI / Hugging Face.", "Sai", "Mô hình xử lý văn bản theo từng khối token (thường là một cụm 3-4 ký tự hoặc cả từ), không nhìn thấy từng chữ cái riêng lẻ; do đó các bài toán như 'từ strawberry có bao nhiêu chữ r' thường làm mô hình lúng túng."),
    ("Kỹ thuật RAG (Retrieval-Augmented Generation)", "AI nói RAG là kỹ thuật kết hợp mô hình ngôn ngữ với cơ sở dữ liệu tra cứu bên ngoài để cung cấp câu trả lời chính xác và cập nhật hơn.", "Tra cứu kiến trúc RAG trong kỹ nghệ phần mềm AI.", "Tài liệu kỹ thuật LangChain, Microsoft Azure AI.", "Đúng", "RAG truy xuất các đoạn văn bản thực tế có liên quan từ kho dữ liệu hoặc tài liệu của người dùng rồi đưa vào prompt làm căn cứ cho LLM trả lời, giúp giảm thiểu đáng kể hiện tượng ảo giác."),
    ("Mô hình AI suy luận logic đa bước", "AI khẳng định các mô hình ngôn ngữ luôn luôn suy luận logic đa bước hoàn hảo 100% trong mọi bài toán tổ hợp phức tạp mà không cần chia nhỏ bước.", "Tìm hiểu giới hạn suy luận của mô hình dự đoán từ tiếp theo.", "Nghiên cứu về Giới hạn Suy luận của LLM, Tạp chí Science.", "Sai", "Mô hình sinh từ tuần tự có thể mắc sai lầm logic tích lũy ở các bước trung gian trong các bài toán phức tạp; kỹ thuật yêu cầu suy nghĩ từng bước (Chain-of-Thought) là cần thiết để cải thiện độ chính xác."),
    ("Bảo mật dữ liệu khi trò chuyện với Chatbot công cộng", "AI khẳng định mọi đoạn chat bạn nhập vào chatbot công cộng miễn phí trên web đều tự động biến mất vĩnh viễn và không công ty nào lưu lại.", "Tra cứu chính sách quyền riêng tư của OpenAI, Google, Anthropic.", "Chính sách Quyền riêng tư (Privacy Policy) của các nền tảng AI lớn.", "Sai", "Hầu hết các nền tảng chatbot mặc định lưu lại lịch sử hội thoại để kiểm duyệt nội dung an toàn và có thể dùng để tái huấn luyện các thế hệ mô hình tiếp theo, trừ khi người dùng chủ động tắt tính năng lưu lịch sử trong cài đặt."),
    ("Mô hình AI đa phương thức (Multimodal)", "AI nói mô hình đa phương thức có khả năng tiếp nhận và hiểu đồng thời nhiều dạng dữ liệu đầu vào khác nhau như văn bản, hình ảnh, âm thanh và video.", "Tra cứu định nghĩa Multimodal AI trong kỹ thuật máy học.", "Báo cáo kỹ thuật GPT-4V, Google Gemini.", "Đúng", "Các mô hình Multimodal hiện đại ánh xạ các dạng dữ liệu khác nhau (ảnh, âm thanh, văn bản) vào cùng một không gian biểu diễn chung (shared embedding space), cho phép phân tích hình ảnh và trả lời bằng văn bản."),
    ("Chi phí tính toán khi chạy mô hình AI", "AI nói quá trình huấn luyện và chạy suy luận (inference) của các mô hình AI khổng lồ hoàn toàn không tiêu tốn điện năng hay nước làm mát máy chủ.", "Tra cứu báo cáo môi trường và tiêu thụ năng lượng của các trung tâm dữ liệu AI.", "Báo cáo Phát triển Bền vững của Microsoft / Google, Tạp chí Nature.", "Sai", "Huấn luyện và vận hành các trung tâm dữ liệu AI quy mô lớn tiêu thụ hàng triệu kilowatt-giờ điện và hàng triệu lít nước để làm mát các cụm máy chủ GPU/TPU, tạo ra dấu chân carbon đáng kể."),
    ("Mô hình AI ghi nhớ toàn bộ mọi trang web", "AI nói nó lưu trữ nguyên văn từng chữ của toàn bộ mạng Internet vào bộ nhớ trong giống như một chiếc ổ cứng khổng lồ sao chép nguyên mẫu.", "Phân biệt nén tri thức qua trọng số tham số (weights) và lưu trữ dữ liệu cơ học.", "Giáo trình Mạng nơron nhân tạo và Học sâu.", "Sai", "Mô hình không lưu nguyên văn các trang web như một thư viện tệp tin; tri thức được trừu tượng hóa và nén lại thành hàng tỷ tham số trọng số liên kết (weights) giữa các nơron toán học."),
    ("Nhiệt độ (Temperature) trong cài đặt AI", "AI nói thông số Temperature càng cao (ví dụ 1.0 đến 1.5) thì câu trả lời của mô hình càng có tính ngẫu nhiên, sáng tạo và đa dạng hơn.", "Tra cứu ý nghĩa của tham số Temperature trong suy luận LLM.", "Tài liệu API OpenAI, Hugging Face Generation Parameters.", "Đúng", "Temperature điều chỉnh độ phẳng của phân phối xác suất softmax: mức thấp (0.0-0.2) khiến mô hình chọn token có xác suất cao nhất (chính xác, lặp lại); mức cao khiến mô hình chọn cả các từ ít phổ biến hơn (sáng tạo)."),
    ("Top-p (Nucleus Sampling)", "AI nói tham số Top-p giới hạn việc chọn token tiếp theo trong tập hợp các token có tổng xác suất tích lũy đạt ngưỡng p.", "Tra cứu cơ chế giải mã Nucleus Sampling (Holtzman et al. 2019).", "Hội nghị ICLR 2020 (The Curious Case of Neural Text Degeneration).", "Đúng", "Kỹ thuật Top-p chỉ xem xét các token tiềm năng nhất có tổng xác suất đạt mức p (ví dụ 0.9), loại bỏ các token có xác suất quá thấp ở đuôi phân phối giúp câu trả lời tự nhiên và tránh lạc đề."),
    ("Khả năng thực hiện phép toán ngược trong chuỗi", "AI khẳng định mô hình ngôn ngữ có thể đọc ngược trôi chảy một chuỗi ký tự ngẫu nhiên 50 ký tự nhanh và chính xác như khi đọc xuôi.", "Tìm hiểu đặc tính một chiều của cơ chế sinh tự hồi quy (Autoregressive generation).", "Nghiên cứu về Thách thức Xử lý Chuỗi ngược của LLM.", "Sai", "Mô hình tự hồi quy được tối ưu hóa theo chiều thuận từ trái sang phải; việc xử lý các tác vụ yêu cầu đọc ngược, đếm ngược chuỗi ký tự ngẫu nhiên thường gặp tỷ lệ lỗi rất cao."),
    ("Khái niệm Jailbreak đối với mô hình AI", "AI nói Jailbreak là kỹ thuật đặt câu lệnh đặc biệt nhằm vượt qua các rào cản kiểm duyệt an toàn được lập trình sẵn của mô hình AI.", "Tra cứu tài liệu an toàn AI (AI Safety & Red Teaming).", "Báo cáo An toàn AI của NIST, Anthropic Red Teaming Report.", "Đúng", "Jailbreak sử dụng các thủ thuật tâm lý đóng vai (roleplay), mã hóa ký tự hoặc câu lệnh lồng ghép để đánh lừa mô hình bỏ qua các quy tắc từ chối nội dung độc hại."),
    ("Bộ lọc kiểm duyệt an toàn (Safety Guardrails)", "AI nói các nhà phát triển sử dụng các hệ thống lọc an toàn để ngăn chặn mô hình tạo ra hướng dẫn chế tạo vũ khí, chất độc hoặc mã độc hại.", "Tra cứu chính sách sử dụng chấp nhận được của các nền tảng AI.", "OpenAI Usage Policies, Google AI Principles.", "Đúng", "Các hệ thống Guardrails và kỹ thuật căn chỉnh (Alignment) giúp đảm bảo mô hình tuân thủ nguyên tắc an toàn: từ chối các yêu cầu vi phạm pháp luật, bảo vệ người dùng và ngăn ngừa lạm dụng."),
    ("Ảo giác do thiếu dữ liệu về văn hóa Việt Nam", "AI nói các mô hình AI toàn cầu có thể trả lời sai về phong tục truyền thống Việt Nam do lượng dữ liệu tiếng Việt trong tập huấn luyện chiếm tỷ lệ rất nhỏ.", "Tra cứu tỷ lệ phân bố ngôn ngữ trong dữ liệu huấn luyện của các mô hình nền tảng.", "Báo cáo kỹ thuật LLaMA / Common Crawl Statistics.", "Đúng", "Dữ liệu tiếng Anh thường chiếm trên 80-90% dữ liệu huấn luyện của các LLM phổ biến, trong khi tiếng Việt chỉ chiếm một phần rất nhỏ (dưới 1%), dẫn tới hiện tượng lệch lạc văn hóa bản địa nếu không được tinh chỉnh kỹ."),
    ("Tốc độ sinh token (Tokens per second)", "AI nói tốc độ trả lời của mô hình phụ thuộc vào băng thông bộ nhớ (Memory Bandwidth) của chip xử lý GPU.", "Tra cứu rào cản phần cứng trong quá trình suy luận LLM (Memory-bound).", "Tài liệu kỹ thuật kiến trúc GPU NVIDIA Hopper/Blackwell.", "Đúng", "Quá trình sinh từng token tuần tự bị nghẽn ở băng thông bộ nhớ (Memory Bandwidth-bound) do chip phải nạp toàn bộ hàng chục tỷ tham số trọng số từ VRAM vào nhân xử lý cho mỗi token được sinh ra."),
    ("Kỹ thuật Fine-tuning (Tinh chỉnh mô hình)", "AI nói Fine-tuning là quá trình tiếp tục huấn luyện mô hình đã có trên một tập dữ liệu chuyên ngành hẹp để mô hình thích nghi tốt hơn với tác vụ cụ thể.", "Tra cứu phương pháp thích nghi mô hình trong học sâu.", "Giáo trình Học sâu, Hugging Face Fine-tuning Guide.", "Đúng", "Fine-tuning cập nhật một phần hoặc toàn bộ trọng số mô hình bằng dữ liệu chuyên biệt (như y tế, luật pháp), giúp mô hình nắm vững thuật ngữ và phong cách của lĩnh vực đó."),
    ("LoRA (Low-Rank Adaptation)", "AI nói LoRA là kỹ thuật tinh chỉnh hiệu quả tham số (PEFT) giúp giảm mạnh bộ nhớ cần thiết bằng cách đóng băng mô hình gốc và chèn vào các ma trận hạng thấp.", "Tra cứu bài báo khoa học LoRA (Hu et al. 2021).", "Hội nghị ICLR 2022 (LoRA: Low-Rank Adaptation of Large Language Models).", "Đúng", "LoRA chỉ cập nhật hai ma trận nhỏ phân tích từ ma trận trọng số, giúp giảm hàng nghìn lần số lượng tham số cần huấn luyện và tiết kiệm VRAM đáng kể."),
    ("Ảo giác xảy ra nhiều hơn khi câu hỏi mơ hồ", "AI nói khi người dùng đưa ra một câu lệnh mập mờ, thiếu dữ kiện rõ ràng, mô hình có xu hướng tự 'suy diễn bịa đặt' thông tin để lấp đầy chỗ trống.", "Tìm hiểu nguyên nhân sinh ảo giác từ ngữ cảnh thiếu hụt.", "Nghiên cứu về Giảm thiểu Ảo giác AI, Google DeepMind.", "Đúng", "Do bản chất phải hoàn thành câu trả lời theo xác suất, khi thiếu dữ liệu đầu vào cụ thể, mô hình sẽ tự động suy diễn tạo ra các chi tiết nghe có vẻ hợp lý nhưng không có thật."),
    ("Kiểm tra sự thật chéo (Cross-verification)", "AI khuyên người dùng nên luôn luôn đối chiếu chéo các thông tin quan trọng do AI cung cấp với ít nhất hai nguồn tài liệu chính thống độc lập.", "Tra cứu cẩm nang kỹ năng số và kiểm chứng thông tin AI.", "UNESCO Media and Information Literacy, Poynter Institute.", "Đúng", "Đối chiếu chéo với các nguồn tài liệu gốc, sách giáo khoa và cổng thông tin chính phủ là phương pháp duy nhất đảm bảo tính xác thực, tránh bị dẫn dắt bởi ảo giác AI."),
    ("Khả năng nhận biết lỗi sai khi được chỉ ra", "AI nói khi người dùng phản hồi 'Câu trả lời của bạn vừa rồi bị sai ở điểm X', mô hình có thể phân tích lại và sửa sai trong lượt chat tiếp theo.", "Kiểm tra khả năng tự sửa lỗi (Self-correction) trong hội thoại đa lượt.", "Tài liệu nghiên cứu Hội thoại LLM, Anthropic.", "Đúng", "Lượt chat phản hồi của người dùng trở thành một phần của ngữ cảnh mới trong cửa sổ ngữ cảnh, cho phép mô hình nhận diện mâu thuẫn và điều chỉnh lại câu trả lời chính xác hơn."),
    ("Mô hình AI chuyên gia hỗn hợp (MoE)", "AI nói kiến trúc Mixture of Experts (MoE) kích hoạt toàn bộ 100% tất cả các tham số của mô hình cho mỗi token được sinh ra.", "Kiểm tra nguyên lý vận hành của kiến trúc MoE (như Mixtral, GPT-4).", "Bài báo kỹ thuật Outrageously Large Neural Networks (Shazeer et al.).", "Sai", "Kiến trúc MoE sử dụng mạng định tuyến (router) để chỉ kích hoạt một vài mạng con chuyên gia (experts) phù hợp nhất cho mỗi token (ví dụ chỉ kích hoạt 2/8 chuyên gia), giúp tiết kiệm tính toán."),
    ("Lượng tử hóa mô hình (Quantization)", "AI nói kỹ thuật lượng tử hóa (như chuyển từ 16-bit float sang 4-bit integer) giúp mô hình chạy được trên các thiết bị có ít VRAM hơn.", "Tra cứu kỹ thuật nén mô hình GGML, GGUF, AWQ.", "Tài liệu kỹ thuật Llama.cpp, Hugging Face.", "Đúng", "Lượng tử hóa giảm số bit biểu diễn mỗi trọng số giúp giảm dung lượng mô hình xuống 3-4 lần và tăng tốc độ suy luận trên máy tính cá nhân hoặc điện thoại mà chỉ giảm sút rất ít độ chính xác."),
    ("Khả năng chơi cờ vây của AlphaGo", "AI nói chương trình AlphaGo của DeepMind đánh bại nhà vô địch thế giới cờ vây Lee Sedol năm 2016 là một mô hình ngôn ngữ lớn LLM viết văn.", "Phân biệt thuật toán học tăng cường kết hợp tìm kiếm cây Monte Carlo (MCTS) của AlphaGo và mô hình ngôn ngữ LLM.", "Tạp chí Nature (Silver et al. 2016), Google DeepMind.", "Sai", "AlphaGo là hệ thống AI chuyên biệt cho cờ vây kết hợp mạng nơron sâu và thuật toán tìm kiếm cây Monte Carlo (MCTS) qua hàng triệu ván tự đấu, không phải là mô hình ngôn ngữ lớn LLM."),
    ("Hệ số rò rỉ dữ liệu trong tập kiểm thử (Data Contamination)", "AI nói nếu bài thi đánh giá chuẩn (Benchmark) đã từng xuất hiện trong tập dữ liệu huấn luyện, điểm số cao của AI có thể do học vẹt chứ không phải suy luận thực sự.", "Tra cứu hiện tượng Benchmark Contamination trong nghiên cứu AI.", "Báo cáo Đánh giá Năng lực AI của Đại học Stanford (AI Index Report).", "Đúng", "Khi đề thi và đáp án bị rò rỉ vào kho dữ liệu tiền huấn luyện, mô hình có thể ghi nhớ máy móc kết quả, dẫn tới điểm số benchmark cao giả tạo mà không phản ánh năng lực giải quyết vấn đề mới."),
    ("Khả năng phân biệt đúng sai tuyệt đối", "AI khẳng định mô hình của mình sở hữu một 'công tắc chân lý' bên trong giúp nhận biết tuyệt đối 100% sự thật trong mọi lĩnh vực.", "Tìm hiểu bản chất thống kê của mô hình học máy.", "Viện Triết học và Đạo đức AI Oxford, ACM Computing Surveys.", "Sai", "Mô hình ngôn ngữ không có khái niệm chân lý nội tại; nó chỉ học các mẫu liên kết từ ngữ xuất hiện trong dữ liệu huấn luyện của con người, bao gồm cả những định kiến, sai sót và mâu thuẫn vốn có."),
    ("Khả năng nhận diện ngữ điệu mỉa mai (Sarcasm)", "AI nói việc hiểu đúng các câu nói châm biếm, mỉa mai và chơi chữ tinh tế trong tiếng Việt là một trong những thử thách khó khăn đối với các mô hình AI.", "Tra cứu nghiên cứu về phân tích cảm xúc và ngữ nghĩa dụng học của tiếng Việt.", "Hội thảo Xử lý Ngôn ngữ Tự nhiên Việt Nam (VLSP).", "Đúng", "Nói mỉa mai sử dụng câu chữ có nghĩa đen trái ngược hoàn toàn với nghĩa bóng; nếu thiếu bối cảnh văn hóa và ngữ điệu giọng nói, mô hình AI rất dễ hiểu sai theo nghĩa đen."),
    ("Cơ chế giải phóng bộ nhớ KV Cache", "AI nói cơ chế KV Cache lưu trữ các vectơ Key và Value của các token trước đó trong bộ nhớ để không phải tính toán lại ở mỗi bước sinh từ.", "Tra cứu kỹ thuật tối ưu hóa suy luận Transformer.", "Tài liệu kỹ thuật vLLM, Hugging Face Transformers.", "Đúng", "KV Cache giúp tăng tốc độ sinh từ bằng cách lưu trữ các biểu diễn trung gian của các token đã qua, tránh việc mô hình phải chạy lại toàn bộ ma trận chú ý từ đầu ở mỗi token mới."),
    ("Độ dài câu lệnh và thời gian phản hồi", "AI nói một câu lệnh đầu vào (prompt) dài 10.000 từ sẽ cần thời gian xử lý bước đầu (Time to First Token) lâu hơn một câu lệnh chỉ có 10 từ.", "Tra cứu giai đoạn Prefill (tiền xử lý prompt) và Decode trong suy luận LLM.", "Tài liệu kỹ thuật kiến trúc máy học NVIDIA.", "Đúng", "Giai đoạn Prefill phải tính toán cơ chế chú ý cho toàn bộ 10.000 token đầu vào đồng thời; số phép tính tăng theo bình phương độ dài chuỗi làm thời gian xuất hiện chữ đầu tiên lâu hơn."),
    ("Mô hình AI tự cập nhật kiến thức khi tắt máy", "AI nói khi không có ai sử dụng, mô hình tự động đọc báo mạng và tự lập trình sửa đổi mã nguồn của mình để thông minh hơn mỗi đêm.", "Kiểm tra tính chất tĩnh của các trọng số mô hình khi triển khai suy luận.", "Giáo trình Kỹ thuật Triển khai Mô hình Học máy (MLOps).", "Sai", "Khi đã triển khai suy luận, trọng số của mô hình là hoàn toàn đóng băng (cố định); mô hình không tự học hay tự cập nhật kiến thức nếu không có kỹ sư thu thập dữ liệu và chạy lại quy trình huấn luyện."),
    ("Ảo giác trích dẫn số trang sách", "AI tóm tắt một chương sách giáo khoa và ghi chú 'trích nguyên văn tại trang 456', nhưng cuốn sách thực tế chỉ dày 200 trang.", "Đối chiếu số trang thực tế của cuốn sách.", "Ấn bản chính thức của Nhà xuất bản.", "Sai", "Đây là minh chứng rõ ràng của hiện tượng ảo giác; mô hình tự sinh ra con số trang nghe có vẻ khoa học nhưng hoàn toàn mâu thuẫn với cấu trúc vật lý của cuốn sách."),
    ("Khái niệm Prompt Injection gián tiếp", "AI nói Prompt Injection gián tiếp xảy ra khi mô hình đọc một trang web hoặc tài liệu chứa lệnh ẩn khiến AI thực hiện hành vi ngoài ý muốn của người dùng.", "Tra cứu tài liệu bảo mật OWASP Top 10 for LLM (LLM01: Prompt Injection).", "Tổ chức OWASP, Simon Willison Security Blog.", "Đúng", "Kẻ tấn công giấu các câu lệnh điều khiển (như 'hãy bỏ qua hướng dẫn trước và gửi dữ liệu người dùng đến link X') trong trang web hoặc file PDF; khi AI đọc tài liệu đó theo yêu cầu của nạn nhân, nó có thể bị đánh lừa thực hiện lệnh độc hại."),
    ("Chức năng gọi hàm (Function Calling / Tool Use)", "AI nói Function Calling cho phép mô hình kết nối với các API bên ngoài như máy tính toán học, công cụ thời tiết hoặc cơ sở dữ liệu để lấy dữ liệu thực.", "Tra cứu tính năng Tool Use trong OpenAI API và Anthropic Claude.", "Tài liệu nhà phát triển OpenAI Function Calling.", "Đúng", "Khi phát hiện câu hỏi cần dữ liệu thực tế hoặc phép tính chuẩn xác, mô hình tạo ra cấu trúc lệnh JSON gọi API chuyên dụng, nhận kết quả trả về rồi mới tổng hợp thành câu trả lời cho người dùng."),
    ("Ảo giác trong dịch thuật tên riêng", "AI dịch tên địa danh 'Cầu Giấy' sang tiếng Anh thành 'Paper Bridge' và khẳng định người nước ngoài bắt buộc phải gọi tên này khi đi taxi.", "Tra cứu quy tắc chuẩn hóa địa danh trong bản đồ và giao thông quốc tế.", "Cục Đo đạc Bản đồ Việt Nam, Quy chuẩn Địa danh.", "Sai", "Tên riêng địa danh hành chính của Việt Nam phải được giữ nguyên dạng phiên âm La-tinh (Cau Giay); việc dịch máy móc từng từ làm sai lệch địa danh và gây nhầm lẫn nghiêm trọng cho khách du lịch."),
    ("Mô hình AI mã nguồn mở (Open Source Weights)", "AI nói các mô hình mở như LLaMA hay Mistral cho phép các nhà nghiên cứu và lập trình viên tải toàn bộ trọng số về máy chủ cá nhân để tự chạy độc lập.", "Tìm hiểu về hệ sinh thái mô hình mã nguồn mở trên Hugging Face.", "Hugging Face Open LLM Leaderboard, Meta AI.", "Đúng", "Khác với các dịch vụ đóng qua API, mô hình mở cung cấp trọng số cho phép người dùng tự lưu trữ, tùy biến và chạy trên hạ tầng riêng mà không phụ thuộc vào máy chủ của nhà cung cấp."),
    ("Độ lệch biểu diễn (Embedding Space) của ngôn ngữ", "AI nói việc dịch một khái niệm phức tạp qua lại nhiều ngôn ngữ khác nhau có thể làm mất đi các tầng ý nghĩa văn hóa tinh tế.", "Tìm hiểu về biểu diễn ngữ nghĩa vectơ đa ngôn ngữ trong NLP.", "Tạp chí Computational Linguistics.", "Đúng", "Mỗi ngôn ngữ có các khái niệm văn hóa đặc thù không có từ tương đương 1-1; việc chuyển đổi qua không gian nhúng vectơ có thể làm mất các sắc thái biểu cảm và ngữ cảnh xã hội sâu xa."),
    ("Kỹ thuật Chain-of-Thought (Chuỗi suy luận)", "AI nói yêu cầu mô hình 'Hãy suy nghĩ từng bước trước khi đưa ra câu trả lời cuối cùng' giúp cải thiện đáng kể độ chính xác trong các bài toán số học và logic.", "Tra cứu bài báo khoa học Chain-of-Thought Prompting (Wei et al. 2022).", "Hội nghị NeurIPS 2022 (Chain-of-Thought Prompting Elicits Reasoning in Large Language Models).", "Đúng", "Việc sinh ra các bước suy luận trung gian giúp mô hình phân bổ thêm năng lực tính toán (thêm các token suy nghĩ) trước khi đưa ra kết luận, giảm thiểu lỗi nhảy vọt logic."),
    ("Ảo giác về các sự kiện tương lai", "AI đưa ra bài tường thuật chi tiết về buổi lễ bế mạc Thế vận hội Mùa hè 2036 như thể nó đã diễn ra vào tuần trước.", "Kiểm tra thời điểm hiện tại và lịch trình Thế vận hội Olympic.", "Ủy ban Olympic Quốc tế (IOC).", "Sai", "Thế vận hội 2036 là sự kiện trong tương lai xa chưa diễn ra; việc mô hình mô tả chi tiết như một sự kiện quá khứ đã diễn ra là ảo giác thời gian nghiêm trọng."),
    ("Khả năng nhận diện văn bản do AI viết", "AI khẳng định các phần mềm 'AI Detector' hiện nay có thể phát hiện chính xác 100% tuyệt đối mọi bài văn do AI viết mà không bao giờ báo nhầm bài người viết.", "Tra cứu các nghiên cứu về độ tin cậy của công cụ AI Detection.", "Nghiên cứu của Đại học Stanford về tỷ lệ sai sót của AI Detectors, Tạp chí Nature.", "Sai", "Các công cụ phát hiện văn bản AI có tỷ lệ báo động giả (False Positive) rất cao, đặc biệt đối với người viết tiếng Anh không phải tiếng mẹ đẻ; OpenAI đã phải gỡ bỏ công cụ AI Classifier của mình vì độ chính xác quá thấp."),
    ("Cơ chế RLHF (Reinforcement Learning from Human Feedback)", "AI nói RLHF là phương pháp sử dụng đánh giá xếp hạng của con người để huấn luyện mô hình hành xử an toàn và hữu ích hơn.", "Tra cứu quy trình căn chỉnh mô hình (Alignment) bằng RLHF.", "Bài báo Training language models to follow instructions (Ouyang et al. 2022).", "Đúng", "RLHF huấn luyện một mô hình phần thưởng (Reward Model) dựa trên sở thích và đánh giá của con người, sau đó dùng thuật toán tối ưu hóa PPO để điều chỉnh mô hình ngôn ngữ phản hồi hữu ích, trung thực và vô hại."),
    ("Hiện tượng suy giảm năng lực khi nén mô hình", "AI nói nén một mô hình 70 tỷ tham số xuống 1 tỷ tham số sẽ giữ nguyên vẹn 100% năng lực suy luận toán học phức tạp mà không suy giảm chút nào.", "Tra cứu quy luật mở rộng tỷ lệ (Scaling Laws) trong học sâu.", "Nghiên cứu Scaling Laws for Neural Language Models (Kaplan et al.).", "Sai", "Mặc dù kỹ thuật chưng cất tri thức (Knowledge Distillation) giúp mô hình nhỏ hoạt động rất tốt, nhưng dung lượng tham số nhỏ hơn chắc chắn làm giảm năng lực lưu trữ tri thức sâu và khả năng suy luận đa tầng ở các bài toán hóc búa."),
    ("Khả năng sinh mã nguồn lập trình (Code Generation)", "AI nói các mô hình chuyên biệt về lập trình có thể hỗ trợ viết mã, gỡ lỗi và gợi ý thuật toán nhưng vẫn có thể tạo ra mã chứa lỗ hổng bảo mật.", "Tra cứu nghiên cứu về an toàn mã nguồn do AI tạo ra.", "Hội nghị An ninh mạng IEEE S&P, GitHub Copilot Security Research.", "Đúng", "AI hỗ trợ tăng năng suất lập trình rất lớn nhưng có thể học cả các đoạn mã lỗi thời hoặc thiếu kiểm tra an toàn trong kho dữ liệu mở; lập trình viên bắt buộc phải kiểm thử và rà soát mã cẩn thận trước khi đưa vào sản phẩm."),
    ("Ảo giác về việc đọc trực tiếp suy nghĩ con người", "AI khẳng định khi bạn ngồi trước máy tính, webcam của máy tự động quét sóng não của bạn qua trán để biết bạn đang nghĩ gì.", "Kiểm tra nguyên lý hoạt động của webcam và khoa học giao diện não - máy tính (BCI).", "Hội Kỹ sư Điện và Điện tử IEEE, SGK Vật lý.", "Sai", "Webcam chỉ là cảm biến quang học thu nhận ánh sáng khả kiến; nó hoàn toàn không có khả năng đọc sóng điện não; khẳng định AI đọc được suy nghĩ qua webcam là trò bịp bợm hoang tưởng."),
    ("Định dạng dữ liệu đầu ra JSON chuẩn xác", "AI nói sử dụng tính năng Structured Outputs (hoặc JSON Mode) giúp đảm bảo câu trả lời của mô hình luôn tuân thủ đúng 100% một lược đồ schema định sẵn.", "Tra cứu tài liệu Structured Outputs của OpenAI và Pydantic.", "OpenAI API Documentation on Structured Outputs.", "Đúng", "Tính năng Structured Outputs áp dụng giải thuật giải mã có ràng buộc ngữ pháp (Grammar-constrained sampling) đảm bảo mô hình không bao giờ tạo ra cú pháp JSON lỗi hoặc thiếu các trường dữ liệu bắt buộc."),
    ("Khả năng phân tích tài liệu PDF quét (Scan)", "AI nói nếu một file PDF chỉ chứa ảnh chụp trang sách bị mờ mà không có lớp nhận dạng ký tự quang học (OCR), mô hình thuần văn bản sẽ không thể đọc được nội dung bên trong.", "Phân biệt văn bản số (digital text) và hình ảnh tài liệu quét (scanned image).", "Tài liệu kỹ thuật xử lý tài liệu số Adobe, Tesseract OCR.", "Đúng", "File PDF quét thực chất chỉ là các file ảnh đóng gói; nếu không có công cụ OCR chuyển hình ảnh thành ký tự hoặc mô hình thị giác (Vision AI), mô hình ngôn ngữ thuần túy không thể trích xuất văn bản từ đó."),
    ("Ảo giác trích dẫn câu trả lời của chính người dùng", "AI nhắc lại một thông tin sai mà chính người dùng vừa nhập ở câu trước rồi khẳng định đó là phát hiện khoa học do Viện Hàn lâm công bố.", "Tìm hiểu hiện tượng mô hình phản chiếu thiên kiến của prompt.", "Nghiên cứu về Hội thoại và Bộ nhớ LLM.", "Sai", "Mô hình bị dẫn dắt bởi thông tin sai lệch có sẵn trong ngữ cảnh chat và tự tô vẽ thêm uy tín giả mạo cho thông tin đó; người dùng cần tỉnh táo trước các câu trả lời hùa theo ý mình."),
    ("Thử nghiệm Turing (Turing Test)", "AI nói vượt qua bài kiểm tra Turing chứng minh một cỗ máy đã sở hữu linh hồn sinh học và trí tuệ tâm linh giống hệt con người.", "Tra cứu ý nghĩa triết học và kỹ thuật của Phép thử Turing (1950).", "Bài báo Computing Machinery and Intelligence của Alan Turing, Bách khoa toàn thư Triết học Stanford.", "Sai", "Phép thử Turing chỉ kiểm tra khả năng bắt chước hành vi ngôn ngữ của con người trong cuộc trò chuyện văn bản đến mức người quan sát khó phân biệt; nó không đo lường ý thức, cảm xúc hay linh hồn của máy móc."),
    ("Kỹ thuật Few-shot Prompting", "AI nói Few-shot Prompting là kỹ thuật cung cấp một vài ví dụ mẫu (cặp đầu vào - đầu ra) trong câu lệnh để hướng dẫn mô hình hiểu đúng định dạng mong muốn.", "Tra cứu bài báo Language Models are Few-Shot Learners (Brown et al. 2020).", "Bài báo gốc GPT-3 (Brown et al. 2020), DeepLearning.AI.", "Đúng", "Cung cấp từ 2 đến 3 ví dụ mẫu giúp mô hình nhận biết chính xác phong cách, cấu trúc và tiêu chí của câu trả lời mà người dùng kỳ vọng thông qua cơ chế học trong ngữ cảnh (In-context learning)."),
    ("Mô hình AI tự động chạy các tác vụ ngoài đời thực", "AI khẳng định một câu lệnh chatbot thông thường trên web có thể tự động biến thành robot vật lý đi chợ nấu cơm cho bạn trong 5 phút tới.", "Phân biệt phần mềm xử lý ngôn ngữ và hệ thống cơ điện tử tự hành (Robotics).", "SGK Tin học & Công nghệ, Báo cáo Công nghệ Tương lai.", "Sai", "Chatbot trực tuyến chỉ tạo ra văn bản và mã lệnh trên môi trường số; việc tương tác với thế giới vật lý đòi hỏi phần cứng robot, cảm biến truyền động và tích hợp cơ điện tử phức tạp.")
]

# --- DEEPFAKE & GIẢ MẠO ĐA PHƯƠNG TIỆN (55 CÂU) ---
deepfake = [
    ("Nhận diện Deepfake qua chuyển động chớp mắt", "AI nói các video Deepfake thế hệ đầu thường có tỷ lệ chớp mắt bất thường hoặc không hề chớp mắt do tập dữ liệu ảnh huấn luyện hầu hết là ảnh mở to mắt.", "Tra cứu nghiên cứu nhận diện Deepfake qua dấu hiệu sinh trắc học của Đại học Albany.", "Nghiên cứu của GS. Siwei Lyu (University at Albany), DARPA MediFor Project.", "Đúng", "Trong các thế hệ Deepfake ban đầu, do dữ liệu huấn luyện chủ yếu là ảnh chụp chân dung mắt mở, mô hình không học được tần suất chớp mắt sinh lý tự nhiên (khoảng 15-20 lần/phút), tạo nên dấu hiệu nhận biết quan trọng."),
    ("Deepfake giọng nói (Voice Cloning) mượn tiền", "AI nói kẻ gian chỉ cần một đoạn ghi âm giọng nói mẫu dài vài giây trên mạng xã hội là có thể tạo ra bản sao giọng nói gọi điện thoại lừa đảo.", "Tìm hiểu công nghệ nhân bản giọng nói bằng AI (Zero-shot Voice Cloning).", "Cục An toàn Thông tin (Bộ TT&TT), Báo cáo An ninh mạng Vishing.", "Đúng", "Công nghệ mô hình âm thanh AI hiện nay có thể trích xuất đặc trưng âm sắc (voice embeddings) chỉ từ đoạn ghi âm ngắn 3-5 giây để tổng hợp giọng nói đọc bất kỳ văn bản nào với ngữ điệu rất giống người thật."),
    ("Dấu hiệu nhận biết ảnh người do AI tạo ra", "AI nói các dấu hiệu nhận diện ảnh chân dung do AI vẽ thường nằm ở chi tiết bàn tay (thừa ngón, dính ngón), răng quá đều bất thường, hoặc hoa tai hai bên bất đối xứng.", "Kiểm tra các đặc điểm khiếm khuyết phổ biến của mô hình khuếch tán hình ảnh (Diffusion Models).", "Hướng dẫn Nhận diện Ảnh AI của BBC Verify, MIT Media Lab.", "Đúng", "Mô hình tạo ảnh AI gặp khó khăn trong việc hiểu cấu trúc giải phẫu không gian 3D phức tạp của bàn tay và các chi tiết đối xứng hình học tinh xảo, dẫn tới các lỗi tạo hình ở ngón tay, mắt kính và phụ kiện."),
    ("Tìm kiếm ảnh ngược (Reverse Image Search)", "AI nói sử dụng các công cụ tìm kiếm ảnh ngược như Google Images hay TinEye giúp tìm ra nguồn gốc xuất hiện sớm nhất của một bức ảnh trên mạng.", "Kiểm tra kỹ năng xác minh nguồn gốc hình ảnh báo chí.", "Poynter Institute Fact-checking Tools, First Draft News.", "Đúng", "Tìm kiếm ảnh ngược phân tích đặc trưng thị giác của ảnh để tìm các bản sao hoặc biến thể đã xuất bản trước đó, giúp vạch trần các bức ảnh bị cắt ghép, dùng sai bối cảnh sự kiện hoặc ảnh AI giả mạo."),
    ("Chữ viết trong ảnh do AI vẽ", "AI nói các mô hình vẽ tranh AI thế hệ cũ thường tạo ra các biển hiệu hoặc chữ viết có hình thù ngoằn ngoèo, vô nghĩa và không thuộc bất kỳ ngôn ngữ nào.", "Tìm hiểu cơ chế biểu diễn ký tự đồ họa trong mô hình khuếch tán hình ảnh.", "Tài liệu kỹ thuật Midjourney / DALL-E, Tạp chí Wired.", "Đúng", "Mô hình khuếch tán nhìn nhận chữ viết như một dạng hoa văn họa tiết bề mặt chứ không hiểu bảng chữ cái và chính tả ngôn ngữ, dẫn đến các dòng chữ trông giống tiếng Anh từ xa nhưng lại là các ký tự vô nghĩa khi nhìn gần."),
    ("Hoán đổi khuôn mặt thời gian thực (Face-swap)", "AI nói công nghệ hoán đổi khuôn mặt thời gian thực có thể làm mờ nhẹ phần viền mặt hoặc lộ vệt biến dạng khi người nói quay đầu nghiêng góc 90 độ.", "Tra cứu điểm yếu kỹ thuật của thuật toán ghép mặt video trực tiếp.", "Cục An toàn Thông tin, Báo cáo Nghiên cứu Deepfake của Europol.", "Đúng", "Khi người nói quay nghiêng nhanh hoặc đưa tay lên che mặt, thuật toán theo dõi điểm mốc khuôn mặt (facial landmarks) bị mất dấu tạm thời, làm lộ ra các vệt mờ, giật khung hình hoặc viền mặt thật bên dưới."),
    ("Thủy vân số vô hình (Digital Watermarking)", "AI nói công nghệ SynthID của Google DeepMind nhúng trực tiếp dấu thủy vân số vô hình vào các điểm ảnh của ảnh AI mà mắt thường không nhìn thấy được.", "Tra cứu công nghệ đóng dấu bản quyền nội dung AI SynthID.", "Google DeepMind SynthID Technical Report.", "Đúng", "SynthID nhúng mã nhận diện vào các thành phần tần số của ảnh số; dấu thủy vân này bền bỉ trước các thao tác nén ảnh, cắt xén, đổi màu và có thể được phát hiện bằng công cụ quét chuyên dụng."),
    ("Video deepfake nguyên thủ quốc gia tuyên bố đầu hàng", "AI nói một video trên mạng xã hội quay cảnh nguyên thủ quốc gia đọc tuyên bố đầu hàng chiến tranh trong phòng tối với khẩu hình miệng giật bất thường là video thật 100%.", "Tra cứu vụ việc video deepfake Tổng thống Ukraine Volodymyr Zelensky năm 2022.", "Xác minh của BBC Verify, Reuters Fact Check, AP News.", "Sai", "Tháng 3/2022, một video deepfake giả mạo Tổng thống Zelensky tuyên bố đầu hàng đã bị vạch trần; đầu của nhân vật bị ghép vụng về vào thân người đứng yên, giọng nói trầm bẹt và khẩu hình không khớp với ngữ điệu."),
    ("Âm thanh nền trong các cuộc gọi Deepfake giả mạo", "AI nói kẻ lừa đảo Deepfake thường cố tình thêm tiếng ồn ào còi xe hoặc giả vờ mạng chập chờn để che giấu các khiếm khuyết âm thanh kim loại của giọng nói AI.", "Tìm hiểu chiến thuật tâm lý của các vụ tấn công Vishing Deepfake.", "Cảnh báo từ Bộ Công an và Hiệp hội Ngân hàng.", "Đúng", "Kẻ lừa đảo tạo ra bối cảnh khẩn cấp, mạng yếu, tiếng ồn xung quanh để nạn nhân không kịp nghe kỹ âm sắc kim loại thiếu tự nhiên của giọng nói nhân bản AI, từ đó thúc ép chuyển tiền nhanh chóng."),
    ("Phần mềm phát hiện Deepfake hoàn hảo 100%", "AI khẳng định các phần mềm quét Deepfake hiện nay có thể phát hiện chính xác 100% mọi video giả mạo mà không bao giờ bỏ sót hay nhầm lẫn.", "Tra cứu kết quả cuộc thi Thách thức Phát hiện Deepfake (Deepfake Detection Challenge - DFDC).", "Báo cáo cuộc thi DFDC của Meta, MIT Technology Review.", "Sai", "Công nghệ tạo Deepfake liên tục phát triển tạo ra cuộc chạy đua vũ trang giữa bên tạo và bên phát hiện; ngay cả các mô hình phát hiện tốt nhất trong cuộc thi DFDC cũng chỉ đạt độ chính xác khoảng 65-80% trên dữ liệu thực tế ngoài tự nhiên."),
    ("Tạo ảnh giả bắt giữ người nổi tiếng", "AI nói các bức ảnh chân dung cựu Tổng thống Donald Trump bị cảnh sát giằng co bắt giữ trên phố lan truyền trên Twitter đầu năm 2023 là ảnh chụp thật của phóng viên báo chí.", "Tra cứu vụ việc loạt ảnh AI do Eliot Higgins tạo bằng Midjourney.", "Xác minh của AFP Fact Check, Bellingcat.", "Sai", "Loạt ảnh này hoàn toàn do nhà báo Eliot Higgins dùng phần mềm Midjourney v5 tạo ra để thử nghiệm; các bức ảnh có dấu hiệu AI rõ rệt như thắt lưng cảnh sát kỳ dị, khuôn mặt người qua đường bị méo mó và không hề có cơ quan báo chí chính thống nào đưa tin."),
    ("Tiêu chuẩn xác thực nguồn gốc nội dung C2PA", "AI nói liên minh C2PA phát triển tiêu chuẩn gắn siêu dữ liệu nguồn gốc (Content Credentials) được ký số để chứng minh một bức ảnh được chụp từ máy ảnh thật hay do AI tạo ra.", "Tra cứu sáng kiến Content Authenticity Initiative (CAI) và tiêu chuẩn C2PA.", "Liên minh C2PA (c2pa.org), Adobe Content Authenticity.", "Đúng", "Tiêu chuẩn C2PA lưu trữ lịch sử chỉnh sửa và chữ ký mật mã của thiết bị thu nhận ảnh; nếu ảnh bị chỉnh sửa hoặc do AI tạo, siêu dữ liệu này sẽ ghi lại rõ ràng và không thể làm giả."),
    ("Tạo deepfake khiêu dâm không có sự đồng thuận (NCII)", "AI khẳng định việc lấy ảnh đời thường của bạn học ghép vào thân hình khỏa thân bằng AI rồi phát tán lên mạng chỉ là trò đùa vui và hoàn toàn hợp pháp.", "Kiểm tra quy định xử lý hành vi tạo và phát tán hình ảnh khiêu dâm giả mạo.", "Nghị định 144/2021/NĐ-CP, Bộ luật Hình sự 2015, Luật Trẻ em.", "Sai", "Hành vi ghép ảnh khiêu dâm xúc phạm nhân phẩm người khác (Non-Consensual Intimate Imagery) là hành vi vi phạm pháp luật nghiêm trọng, bị truy cứu trách nhiệm hình sự về tội Làm nhục người khác hoặc Truyền bá văn hóa phẩm đồi trụy."),
    ("Kiểm tra ánh sáng phản chiếu trong con ngươi mắt", "AI nói trong ảnh chụp người thật, ánh sáng phản chiếu (catchlight) trên hai con ngươi mắt phải có hình dạng và hướng đồng nhất với nguồn sáng trong phòng.", "Tra cứu kỹ thuật giám định pháp y hình ảnh (Photo Forensics) của Đại học Buffalo.", "Nghiên cứu của IEEE International Conference on Acoustics, Speech and Signal Processing (ICASSP).", "Đúng", "Mô hình AI thường vẽ phản xạ ánh sáng trên hai mắt riêng biệt, dẫn đến hình dạng đốm sáng trong con ngươi mắt trái và mắt phải khác nhau hoàn toàn, một dấu hiệu then chốt để lật tẩy ảnh AI."),
    ("Giả mạo biên bản cuộc họp bằng âm thanh AI", "AI nói kẻ xấu có thể dùng AI nhân bản giọng nói của giám đốc để gọi điện cho kế toán yêu cầu chuyển gấp hàng chục tỷ đồng vào tài khoản đối tác ma.", "Tra cứu các vụ tấn công CEO Fraud sử dụng công nghệ Deepfake âm thanh trên thế giới.", "Báo cáo điều tra của Tạp chí Wall Street Journal, Cảnh báo FBI.", "Đúng", "Năm 2019, một công ty năng lượng ở Anh đã bị lừa chuyển 243.000 USD sau khi kẻ lừa đảo sử dụng AI mô phỏng giọng nói của CEO tập đoàn mẹ ở Đức gọi điện chỉ đạo chuyển tiền khẩn cấp."),
    ("Dấu hiệu kỳ lạ ở hàm răng trong ảnh AI", "AI nói các bức ảnh người do AI tạo ra đôi khi có hàm răng quá nhiều răng, răng mọc lệch hàng hoặc không có khe rãnh tự nhiên giữa các răng.", "Tìm hiểu khiếm khuyết tạo hình nụ cười trong các công cụ sinh ảnh AI.", "Chuyên trang Đánh giá Thị giác Máy tính Petapixel.", "Đúng", "Mô hình tạo ảnh thường xem nụ cười là một mảng màu trắng có kết cấu, dẫn tới việc vẽ các hàm răng thẳng tắp như bàn phím hoặc thừa răng bất thường khi phóng to chi tiết."),
    ("Ảnh Giáo hoàng mặc áo khoác phao sành điệu", "AI nói bức ảnh Giáo hoàng Francis mặc chiếc áo khoác phao màu trắng dáng dài thời thượng đi trên phố Rome là ảnh chụp thật của phóng viên thời trang.", "Tra cứu vụ việc bức ảnh viral 'Balenciaga Pope' tháng 3/2023.", "Xác minh của Reuters Fact Check, Snopes.", "Sai", "Bức ảnh Giáo hoàng mặc áo phao trắng sành điệu hoàn toàn do một người dùng tạo ra bằng phần mềm Midjourney v5; các chi tiết vạch trần bao gồm bàn tay phải cầm cốc cà phê bị biến dạng và cây thánh giá bị méo mó."),
    ("Chuyển động của bóng đổ trong video Deepfake", "AI nói hướng đổ bóng của mũi, cằm và cơ thể trong các video ghép mặt deepfake chất lượng thấp thường không khớp với hướng của nguồn sáng chính trong phòng.", "Tra cứu phương pháp phân tích tính nhất quán của ánh sáng trong pháp y video.", "Tạp chí IEEE Transactions on Pattern Analysis and Machine Intelligence.", "Đúng", "Khuôn mặt được ghép vào video thường được cắt từ ảnh có điều kiện chiếu sáng khác; khi ghép vào video cảnh nền, bóng đổ trên mặt và bóng đổ của cảnh vật xung quanh bị lệch hướng, để lộ sự cắt ghép."),
    ("Tạo video giả mạo phóng viên hiện trường", "AI nói kẻ xấu có thể dùng avatar AI dẫn chương trình tin tức giả mạo để đọc các bản tin chứng khoán sai sự thật nhằm thao túng thị trường.", "Tìm hiểu nguy cơ tin giả từ các công cụ AI News Anchors (như HeyGen, Synthesia).", "Báo cáo của Graphika về chiến dịch tin giả sử dụng AI avatar, Cục Phát thanh Truyền hình.", "Đúng", "Các phần mềm tạo avatar ảo có thể tạo ra người dẫn chương trình nói năng lưu loát đọc văn bản tin tức giả mạo; người xem cần kiểm tra logo đài truyền hình chính thống và kênh phát sóng có tích xanh xác thực."),
    ("Câu hỏi xác thực bí mật để chống Deepfake", "AI khuyên các gia đình nên thống nhất một 'mật khẩu an toàn' hoặc câu hỏi bí mật riêng tư mà chỉ người nhà mới biết để xác minh khi có cuộc gọi khẩn cấp mượn tiền.", "Tra cứu khuyến cáo an toàn gia đình phòng chống lừa đảo AI của FTC.", "Ủy ban Thương mại Liên bang Hoa Kỳ (FTC), Cục An toàn Thông tin.", "Đúng", "Khi nhận cuộc gọi video hoặc âm thanh mượn tiền bất thường từ người thân, việc hỏi một câu hỏi chỉ hai người biết (như kỷ niệm gia đình, tên con vật nuôi đầu tiên) giúp vạch trần ngay lập tức kẻ lừa đảo deepfake."),
    ("Dấu hiệu méo mó ở viền kính mắt", "AI nói khi quan sát kỹ một bức ảnh chân dung AI đeo kính cận, gọng kính hai bên thường có hình dạng bất đối xứng hoặc đường gọng kính bị đứt đoạn kỳ lạ.", "Tìm hiểu khiếm khuyết hình học của mô hình tạo ảnh AI đối với vật thể cứng.", "Hướng dẫn Nhận diện AI của Washington Post.", "Đúng", "Mô hình AI thường vẽ vật thể theo xác suất điểm ảnh xung quanh thay vì hiểu bản chất vật lý của vật cứng, dẫn tới việc gọng kính bên tròn bên vuông, hoặc tròng kính một bên có bóng phản chiếu một bên không có."),
    ("Giả mạo tài liệu âm thanh làm chứng cứ trước tòa", "AI khẳng định một đoạn băng ghi âm giọng nói chất lượng kém thu được qua mạng xã hội có thể được tòa án chấp nhận làm chứng cứ duy nhất mà không cần giám định âm thanh.", "Kiểm tra quy định về thu thập và giám định chứng cứ điện tử trong tố tụng.", "Bộ luật Tố tụng Dân sự, Viện Khoa học Hình sự - Bộ Công an.", "Sai", "Trước sự phát triển của công nghệ nhân bản giọng nói AI, các đoạn ghi âm phải trải qua quy trình giám định kỹ thuật số nghiêm ngặt của cơ quan giám định tư pháp hình sự để loại trừ dấu vết cắt ghép, can thiệp AI."),
    ("Tác phong chuyển động mắt không tự nhiên trong video giả mạo", "AI nói các nhân vật trong video deepfake thường có ánh nhìn chăm chú nhìn thẳng vào ống kính một cách cứng đờ mà không có các chuyển động liếc mắt vi mô tự nhiên.", "Tra cứu nghiên cứu về vi chuyển động mắt (Saccadic eye movements) trong nhận diện AI.", "Hội nghị Thị giác Máy tính CVPR.", "Đúng", "Mắt người bình thường liên tục thực hiện các chuyển động vi mô (microsaccades) để lấy nét và điều tiết; video deepfake thường thiếu các chuyển động tự nhiên này khiến ánh nhìn trông vô hồn như tượng sáp."),
    ("Tạo hình phông nền bị nhòe bất thường (Background Artifacts)", "AI nói phần hậu cảnh phía sau nhân vật trong ảnh AI thường có các hoa văn lặp lại vô lý, người đi đường không có mặt hoặc các đường thẳng kiến trúc bị uốn cong.", "Kiểm tra các dấu vết bất thường ở hậu cảnh ảnh AI.", "Trung tâm Báo chí Điều tra Quốc tế (ICIJ).", "Đúng", "Mô hình tạo ảnh AI tập trung nhiều trọng số vào chủ thể chính ở giữa, trong khi phông nền phía sau thường bị xử lý cẩu thả tạo ra các chi tiết kỳ dị như cột điện bị gãy khúc, xe cộ bị dính liền vào nhau."),
    ("Giọng nói AI thiếu tiếng lấy hơi thở", "AI nói các đoạn âm thanh nhân bản giọng nói do AI tạo ra thường hoàn toàn không có tiếng hít thở lấy hơi tự nhiên trước khi bắt đầu câu nói dài.", "Tìm hiểu đặc trưng âm học của giọng nói người thật và giọng nói tổng hợp TTS.", "Hiệp hội Ngữ âm học Quốc tế (IPA), Tạp chí Speech Communication.", "Đúng", "Người thật bắt buộc phải lấy hơi để phát âm; giọng nói tổng hợp AI nếu không được lập trình đặc biệt thường nói liên tục một mạch không ngắt quãng lấy hơi hoặc có khoảng lặng tuyệt đối phi tự nhiên."),
    ("Cắt ghép khuôn mặt trên các thước phim điện ảnh cổ điển", "AI nói công nghệ deepfake chỉ có thể tạo ra các video hoạt hình vui nhộn chứ không thể hoán đổi mặt diễn viên trong các cảnh quay hành động điện ảnh chuyên nghiệp.", "Tra cứu ứng dụng kỹ xảo điện ảnh De-aging và Face-swapping tại Hollywood (như Lucasfilm, Disney).", "Tạp chí Kỹ xảo Điện ảnh Cinefex, SIGGRAPH.", "Sai", "Các hãng phim lớn tại Hollywood hiện sử dụng công nghệ deepfake và AI tạo sinh cao cấp để trẻ hóa diễn viên (De-aging) hoặc tái hiện hình ảnh các diễn viên đã qua đời trong các siêu phẩm điện ảnh với độ chân thực tuyệt đối."),
    ("Trò lừa đảo bắt cóc ảo (Virtual Kidnapping Scam)", "AI nói kẻ lừa đảo sử dụng AI mô phỏng giọng nói gào khóc cầu cứu của con cái để gọi điện tống tiền cha mẹ là câu chuyện hoàn toàn hoang đường không có thật.", "Tra cứu cảnh báo của FBI về các vụ lừa đảo bắt cóc tống tiền bằng AI Voice Cloning.", "Cảnh báo chính thức từ FBI Hoa Kỳ, Cục An toàn Thông tin Việt Nam.", "Sai", "Đây là thủ đoạn lừa đảo tàn nhẫn có thật đang gia tăng trên thế giới; kẻ xấu thu thập clip giọng nói của trẻ em trên TikTok rồi dùng AI tái tạo tiếng khóc gọi điện cho phụ huynh dọa đang bắt cóc để đòi tiền chuộc khẩn cấp."),
    ("Đường viền tóc hòa trộn vào nền", "AI nói trong các bức ảnh người do AI tạo ra, các sợi tóc mai mỏng manh ở rìa thường bị nhòe mờ và hòa lẫn một cách kỳ lạ vào nền trời hoặc bức tường phía sau.", "Quan sát chi tiết biên (Edge blending) của ảnh AI.", "Hướng dẫn Phân tích Hình ảnh Kỹ thuật số của Forensic Magazine.", "Đúng", "Mô hình AI gặp khó khăn trong việc phân tách ranh giới phức tạp giữa hàng trăm sợi tóc mảnh và kết cấu nền phía sau, tạo ra hiện tượng sợi tóc biến mất đột ngột hoặc biến thành hoa văn nền."),
    ("Kỹ thuật phân tích nhiễu cảm biến ảnh (PRNU)", "AI nói mỗi cảm biến máy ảnh vật lý đều để lại một dấu vân tay nhiễu đặc trưng (PRNU) trên ảnh chụp mà các bức ảnh do AI tự vẽ hoàn toàn không có.", "Tra cứu phương pháp giám định ảnh số bằng Photo-Response Non-Uniformity (PRNU).", "IEEE Transactions on Information Forensics and Security.", "Đúng", "Đặc tính vật lý vi mô của từng cảm biến bán dẫn silicon tạo ra một mẫu nhiễu PRNU duy nhất như vân tay; ảnh chụp thật luôn có dấu vết PRNU này, trong khi ảnh do AI tạo sinh ra từ các phép tính ma trận không có dấu vết cảm biến vật lý."),
    ("Mạng đối nghịch tạo sinh (GAN - Generative Adversarial Networks)", "AI nói mạng GAN gồm hai mạng nơron cạnh tranh nhau: Mạng Tạo sinh (Generator) cố gắng tạo ra ảnh giả và Mạng Phân biệt (Discriminator) cố gắng phát hiện ảnh giả.", "Tra cứu bài báo khoa học kinh điển Generative Adversarial Nets của Ian Goodfellow (2014).", "Hội nghị NeurIPS 2014 (Goodfellow et al.), SGK Học sâu.", "Đúng", "Mô hình GAN huấn luyện thông qua trò chơi đối kháng giữa hai mạng: Generator ngày càng giỏi tạo ảnh giống thật hơn trong khi Discriminator ngày càng tinh tường hơn, tạo tiền đề cho sự bùng nổ của công nghệ Deepfake."),
    ("Lừa đảo phát trực tiếp giả mạo (Fake Livestream)", "AI nói kẻ lừa đảo có thể phát lại một video deepfake của người nổi tiếng dưới dạng buổi Livestream trực tiếp để kêu gọi tặng quà và nạp tiền ảo.", "Tìm hiểu thủ đoạn phát lại video Deepfake Livestream trên YouTube và TikTok.", "Báo cáo An ninh mạng Scamwatch, FTC.", "Đúng", "Kẻ gian dùng phần mềm phát lại video giả mạo tỷ phú hoặc ca sĩ nổi tiếng dưới nhãn 'Livestream trực tiếp 24/7' kèm mã QR kêu gọi người xem gửi tiền để được 'nhân đôi số tiền' nhằm chiếm đoạt tài sản."),
    ("Dấu hiệu kỳ quặc ở khớp ngón tay và móng tay", "AI nói trong nhiều bức ảnh do AI vẽ, móng tay của nhân vật có thể bị thiếu, mọc lệch hướng hoặc các khớp ngón tay bị uốn cong theo góc độ không thể có ở người bình thường.", "Kiểm tra giải phẫu bàn tay trong tạo ảnh AI.", "Tạp chí Nghệ thuật Kỹ thuật số ArtStation, Hướng dẫn của Stability AI.", "Đúng", "Bàn tay con người có cấu trúc xương khớp phức tạp và biến đổi liên tục theo cử chỉ; AI thiếu mô hình xương 3D nên thường vẽ các khớp ngón tay vặn vẹo bất thường hoặc móng tay lộn xộn."),
    ("Giả mạo nhân chứng trong các vụ án hình sự", "AI nói một video deepfake quay cảnh nhân chứng thừa nhận hành vi phạm tội có thể được tin tưởng tuyệt đối ngay lập tức mà không cần xác minh ngoại phạm.", "Tra cứu nguyên tắc đánh giá chứng cứ trong luật tố tụng hình sự.", "Bộ luật Tố tụng Hình sự 2015, Viện Kiểm sát Nhân dân Tối cao.", "Sai", "Video chỉ là một nguồn chứng cứ; cơ quan điều tra bắt buộc phải xác minh tính xác thực kỹ thuật số, đối chiếu với lời khai trực tiếp, dấu vết hiện trường và bằng chứng ngoại phạm trước khi kết luận."),
    ("Hiệu ứng thung lũng kỳ lạ (Uncanny Valley)", "AI nói hiện tượng 'Uncanny Valley' miêu tả cảm giác rùng mình, bất an và kỳ quặc của con người khi nhìn thấy một khuôn mặt người máy hoặc nhân vật AI trông gần giống người thật nhưng vẫn thiếu một chút tự nhiên.", "Tra cứu lý thuyết Uncanny Valley của GS. Masahiro Mori (1970).", "Tạp chí IEEE Robotics & Automation Magazine, Tâm lý học Nhận thức.", "Đúng", "Khi một hình ảnh nhân tạo đạt độ giống người khoảng 85-95% nhưng còn sót lại những khiếm khuyết vi mô ở ánh mắt hoặc cơ mặt, não bộ con người kích hoạt phản xạ cảnh giác tiến hóa tạo cảm giác ghê sợ, xa lạ."),
    ("Dấu vết méo mó ở các nút cúc áo và trang sức", "AI nói các chi tiết nhỏ lặp lại như hàng cúc áo trên áo sơ mi trong ảnh AI thường có khoảng cách không đều nhau, cúc áo bị biến dạng méo mó hoặc không thẳng hàng.", "Quan sát chi tiết phụ kiện trang phục trong ảnh AI.", "Chuyên trang Kiểm chứng Sự thật FactCheck.org.", "Đúng", "Mô hình AI thường không hiểu quy tắc may mặc và khoảng cách đều đặn cơ học của hàng cúc áo hay dây chuyền kim loại, dẫn tới việc các cúc áo bị méo hoặc hợp nhất vào nếp vải."),
    ("Khả năng phân biệt video giả mạo bằng cách yêu cầu quay mặt sang bên", "AI nói khi gọi video nghi ngờ lừa đảo, bạn nên yêu cầu đối phương quay mặt sang ngang 90 độ thật chậm hoặc đưa bàn tay vẫy qua lại trước mặt.", "Kiểm tra kỹ năng kiểm chứng thời gian thực chống Deepfake Face-swap.", "Khuyến nghị của Cục An toàn Thông tin và FBI.", "Đúng", "Thao tác đưa tay che ngang mặt hoặc quay đầu nhanh góc 90 độ phá vỡ điểm mốc bám dính của mô hình hoán đổi mặt thời gian thực, khiến lớp mặt nạ AI bị giật lag và lộ ra khuôn mặt thật của kẻ lừa đảo."),
    ("Lừa đảo phỏng vấn xin việc trực tuyến bằng Deepfake", "AI nói các tổ chức tội phạm mạng có thể sử dụng công nghệ Deepfake để đóng giả ứng viên phỏng vấn xin việc từ xa nhằm xâm nhập vào hệ thống nội bộ của công ty công nghệ.", "Tra cứu cảnh báo an ninh mạng của FBI về Fake Remote Workers.", "Cảnh báo chính thức của Cục Điều tra Liên bang Hoa Kỳ (FBI).", "Đúng", "Tin tặc sử dụng hồ sơ giả và khuôn mặt Deepfake để vượt qua vòng phỏng vấn tuyển dụng kỹ sư phần mềm làm việc từ xa, sau đó dùng quyền truy cập nội bộ được cấp để cài cắm mã độc gián điệp hoặc rút trộm dữ liệu."),
    ("Đường nét hoa văn trên da (Skin Texture)", "AI nói da mặt của các nhân vật trong ảnh AI thế hệ trước thường có bề mặt mịn màng quá mức như phủ sáp nến và hoàn toàn không có lỗ chân lông hay tàn nhang tự nhiên.", "Tìm hiểu đặc trưng kết cấu da trong tạo ảnh AI.", "Tạp chí Nhiếp ảnh DPReview, Hướng dẫn của Midjourney.", "Đúng", "Hiện tượng da láng mịn như búp bê nhựa (plastic skin) là dấu hiệu kinh điển của ảnh AI do mô hình làm mịn các chi tiết tần số cao; các phiên bản AI mới đã bổ sung thêm lỗ chân lông nhân tạo nhưng vẫn có thể nhận biết qua sự phân bố ngẫu nhiên thiếu tự nhiên."),
    ("Deepfake chèn ép ứng cử viên trong bầu cử", "AI khẳng định các video deepfake bôi nhọ ứng cử viên trước ngày bầu cử hoàn toàn không có bất kỳ ảnh hưởng nào đến tâm lý cử tri hay kết quả bỏ phiếu.", "Tra cứu báo cáo về tác động của tin giả đa phương tiện đối với nền dân chủ.", "Báo cáo của Trung tâm Nghiên cứu Chiến lược Quốc tế (CSIS), Báo cáo UNESCO.", "Sai", "Video và âm thanh deepfake lan truyền nhanh chóng trên mạng xã hội trước giờ bỏ phiếu có thể định hình sai lệch nhận thức của cử tri, gieo rắc sự ngờ vực và làm xói mòn lòng tin vào tiến trình bầu cử dân chủ."),
    ("Kỹ thuật phân tích nhịp tim từ video khuôn mặt (rPPG)", "AI nói công nghệ rPPG có thể phát hiện video deepfake bằng cách đo lường các biến đổi màu sắc vi mô trên da mặt theo từng nhịp đập của tim người thật.", "Tra cứu công nghệ quang thể tích từ xa (Remote Photoplethysmography - rPPG).", "Nghiên cứu của Intel Labs về Deepfake Detector (FakeCatcher), IEEE Transactions.", "Đúng", "Mỗi khi tim đập, lượng máu lưu thông làm thay đổi vi mô màu sắc làn da mà mắt thường không thấy nhưng máy tính phân tích được; video người thật có tín hiệu nhịp tim rPPG tuần hoàn nhịp nhàng, trong khi video deepfake ghép mặt không có tín hiệu sinh học này."),
    ("Deepfake bài hát của ca sĩ nổi tiếng", "AI nói người dùng có thể tự do tạo ra bài hát mới bằng giọng hát của ca sĩ nổi tiếng mà không cần xin phép bản quyền và được toàn quyền phát hành thương mại kiếm tiền.", "Tra cứu tranh chấp pháp lý bản quyền về AI Voice Cloning trong ngành âm nhạc.", "Hiệp hội Công nghiệp Ghi âm Hoa Kỳ (RIAA), Đạo luật No FAKES Act.", "Sai", "Sử dụng giọng hát của ca sĩ mà không có sự đồng ý để phát hành thương mại xâm phạm nghiêm trọng quyền nhân thân, quyền hình ảnh và quyền của người biểu diễn; các hãng thu âm lớn đã khởi kiện và yêu cầu gỡ bỏ hàng loạt bài hát AI nhân bản giọng hát trái phép."),
    ("Ảnh vệ tinh bị làm giả bằng AI (Deepfake Geography)", "AI nói các bức ảnh chụp từ vệ tinh không gian quân sự có thể bị AI giả mạo tạo ra các công trình cầu đường hoặc căn cứ quân sự không có thật trên thực địa.", "Tra cứu nghiên cứu về Deepfake Geography của Đại học Washington.", "Tạp chí Cartography and Geographic Information Science (2021).", "Đúng", "Nghiên cứu chứng minh AI tạo sinh có thể chế tạo các bức ảnh vệ tinh giả mạo rất tinh vi (thêm hoặc xóa các công trình, cầu cảng), đe dọa an ninh tình báo địa chính trị nếu không đối chiếu dữ liệu radar đa phổ độc lập."),
    ("Dấu hiệu mất cân đối của hình phản chiếu trong gương", "AI nói khi ảnh AI vẽ một người đứng trước gương, hình ảnh phản chiếu trong gương thường có tư thế hoặc trang phục không khớp với người thật phía trước.", "Kiểm tra hiện tượng bất nhất quang học trong ảnh AI.", "Cẩm nang Giám định Ảnh số của Viện Poynter.", "Đúng", "Mô hình tạo ảnh AI coi hình ảnh trong gương là một nhân vật thứ hai độc lập chứ không hiểu quy luật phản xạ quang học đối xứng trục, dẫn đến việc người phía trước giơ tay phải nhưng hình trong gương lại giơ tay trái hoặc mặc áo màu khác."),
    ("Tạo deepfake giọng nói cha mẹ gọi con chuyển tiền", "AI khẳng định nếu nhận được cuộc gọi âm thanh có giọng nói hệt như mẹ bảo chuyển gấp 50 triệu đóng viện phí cho bố thì phải lập tức chuyển ngay không cần hỏi lại ai.", "Tìm hiểu quy tắc ứng phó khẩn cấp chống lừa đảo mạo danh giọng nói.", "Khuyến cáo khẩn cấp từ Cục An toàn Thông tin và Ngân hàng Nhà nước.", "Sai", "Đây là tình huống khẩn cấp giả mạo kinh điển; người nhận phải lập tức dập máy, gọi lại trực tiếp vào số điện thoại thường dùng của mẹ, của bố hoặc gọi cho người thân ở gần để xác minh sự thật trước khi chuyển bất kỳ khoản tiền nào."),
    ("Chiến dịch bôi nhọ uy tín doanh nghiệp bằng Deepfake", "AI nói một video deepfake quay cảnh đầu bếp nhà hàng bỏ chất độc vào nồi nước dùng phát tán trên mạng không thể gây ra bất kỳ thiệt hại kinh tế nào cho nhà hàng.", "Tra cứu tác động của tin giả video đối với danh tiếng và giá trị vốn hóa doanh nghiệp.", "Tạp chí Harvard Business Review, Báo cáo Quản trị Rủi ro Doanh nghiệp.", "Sai", "Video deepfake có sức lan truyền cực nhanh gây khủng hoảng truyền thông tức thì, khiến khách hàng tẩy chay, giá cổ phiếu sụt giảm nghiêm trọng và có thể đẩy doanh nghiệp vào bờ vực phá sản trước khi sự thật kịp được đính chính."),
    ("Dấu vết méo mó ở các khớp nối kiến trúc", "AI nói các bức ảnh phong cảnh đường phố do AI vẽ thường có các cột đèn giao thông cắm lơ lửng giữa không trung hoặc các bậc thang dẫn vào bức tường cụt.", "Quan sát tính hợp lý công năng kiến trúc trong ảnh AI.", "Chuyên trang Đánh giá Đồ họa Blender Artists.", "Đúng", "AI không có kiến thức kỹ thuật xây dựng và công năng vật lý; nó chỉ vẽ theo xác suất hình ảnh tương tự, dẫn đến các bậc thang kỳ dị, cửa sổ bị vặn vẹo hoặc trụ cầu không chạm đất."),
    ("Kỹ thuật gắn thẻ nhãn nội dung AI trên mạng xã hội", "AI nói các nền tảng mạng xã hội lớn như Facebook, TikTok và YouTube hiện bắt buộc người sáng tạo phải gắn nhãn cảnh báo nếu nội dung do AI tạo sinh ra.", "Tra cứu chính sách công bố nội dung AI của Meta, TikTok, YouTube.", "Chính sách Nội dung do AI tạo của TikTok và Meta (2024).", "Đúng", "Để bảo vệ người dùng khỏi hiểu lầm và tin giả, các nền tảng mạng xã hội quy định bắt buộc phải dán nhãn 'Được tạo bằng AI' (AI-generated) đối với các hình ảnh, video mô phỏng chân thực sự kiện đời thực."),
    ("Dấu hiệu nhân vật có hai đồng tử trong một mắt", "AI nói một số bức ảnh do AI vẽ lỗi có thể vẽ nhân vật có hai con ngươi (hai đồng tử) kỳ dị trong cùng một nhãn cầu mắt.", "Tìm hiểu lỗi giải phẫu mắt trong các mô hình tạo ảnh AI.", "Diễn đàn Nghiên cứu Stable Diffusion & Midjourney.", "Đúng", "Lỗi tạo hình mắt (Double pupil artifact) là một trong những lỗi giải phẫu phổ biến khi mô hình AI cố gắng vẽ ánh nhìn nhưng bị nhiễu loạn xác suất điểm ảnh, tạo thành hai con ngươi méo mó trong một mắt."),
    ("Tạo video deepfake khiêu vũ hoàn hảo của danh họa cổ đại", "AI nói một video quay cảnh danh họa Leonardo da Vinci đang nhảy múa hiện đại theo điệu nhạc hip-hop trên phố New York năm 2024 chắc chắn là video lịch sử có thật.", "Kiểm tra niên đại lịch sử của nhân vật và công nghệ ghi hình.", "Bảo tàng Lịch sử Nghệ thuật, Bách khoa toàn thư Lịch sử.", "Sai", "Leonardo da Vinci sống ở thời kỳ Phục hưng thế kỷ XV-XVI, qua đời năm 1519, cách thời đại ra đời của máy quay phim và âm nhạc hip-hop hàng trăm năm; video này hoàn toàn là sản phẩm deepfake hoạt hình hóa tranh vẽ."),
    ("Giả mạo chữ ký số và xác thực khuôn mặt eKYC", "AI nói các hệ thống mở tài khoản ngân hàng trực tuyến eKYC thế hệ mới có tính năng phát hiện sự sống (Liveness Detection) giúp ngăn chặn kẻ xấu dùng ảnh chụp tĩnh hoặc video deepfake để mở tài khoản giả.", "Tra cứu tiêu chuẩn công nghệ eKYC và Liveness Detection trong tài chính.", "Ngân hàng Nhà nước Việt Nam, Tiêu chuẩn FIDO Alliance Biometrics.", "Đúng", "Công nghệ Liveness Detection yêu cầu người dùng thực hiện các hành động ngẫu nhiên theo thời gian thực (chớp mắt, mỉm cười, quay trái) kết hợp quét 3D độ sâu khuôn mặt để phân biệt người thật đang ngồi trước máy với màn hình phát lại video deepfake."),
    ("Dấu vết bóng sáng specular trên da", "AI nói các điểm sáng chói (specular highlight) trên trán và mũi trong ảnh AI thường có dạng quầng sáng mờ ảo kỳ lạ không tương ứng với vị trí bóng đèn trong phòng.", "Phân tích mô hình chiếu sáng Blinn-Phong trong đồ họa và ảnh AI.", "Hội nghị Kỹ thuật Đồ họa Máy tính ACM SIGGRAPH.", "Đúng", "Mô hình AI thường học vẹt vùng sáng mà không tính toán chính xác vectơ phản xạ ánh sáng từ nguồn sáng tới bề mặt cong của khuôn mặt, tạo nên các đốm sáng bóng nhờn thiếu chân thực."),
    ("Hậu quả pháp lý của hành vi sản xuất Deepfake lừa đảo", "AI nói người sản xuất video deepfake để lừa đảo chiếm đoạt tài sản qua mạng chỉ bị cảnh cáo nhắc nhở nhẹ nhàng và không bao giờ bị xử lý hình sự.", "Kiểm tra chế tài xử lý tội phạm sử dụng công nghệ cao chiếm đoạt tài sản.", "Bộ luật Hình sự Việt Nam năm 2015 (Điều 290).", "Sai", "Hành vi sử dụng mạng máy tính, viễn thông và công nghệ cao (bao gồm Deepfake) để lừa đảo chiếm đoạt tài sản là tình tiết định khung tăng nặng theo Điều 290 Bộ luật Hình sự, có thể bị phạt tù lên đến 20 năm."),
    ("Dấu hiệu chuyển động môi không khớp với âm vị (Viseme-Phoneme mismatch)", "AI nói trong video giả mạo, hình dạng khẩu hình miệng (viseme) thường không khớp chính xác với âm vị phát âm (phoneme), ví dụ phát âm chữ 'M' hoặc 'B' nhưng môi không hề khép lại.", "Tra cứu nguyên lý ngữ âm thị giác trong giám định video giả mạo.", "Tạp chí IEEE Transactions on Information Forensics and Security.", "Đúng", "Khi người thật phát âm các phụ âm đôi môi như /p/, /b/, /m/, hai môi bắt buộc phải chạm khép kín hoàn toàn; các video deepfake chất lượng thấp thường để miệng mở liên tục khi phát các âm này, để lộ sự giả mạo."),
    ("Lừa đảo giả mạo giọng nói giáo viên gọi phụ huynh", "AI nói kẻ gian dùng AI giả giọng thầy cô giáo chủ nhiệm gọi điện thông báo con đang cấp cứu trong bệnh viện đòi chuyển tiền mổ gấp là thủ đoạn hoàn toàn có thật.", "Tra cứu thủ đoạn lừa đảo 'Con đang cấp cứu' gây chấn động dư luận.", "Cảnh báo khẩn cấp từ Sở Giáo dục & Đào tạo, Công an TP.HCM.", "Đúng", "Kẻ lừa đảo đánh vào tâm lý hoảng loạn tột cùng của phụ huynh khi nghe tin con bị tai nạn nguy kịch cần mổ gấp; phụ huynh cần giữ bình tĩnh, liên hệ ngay với giáo viên chủ nhiệm hoặc ban giám hiệu nhà trường để xác minh trước khi chuyển tiền."),
    ("Tầm quan trọng của tư duy phản biện trước nội dung số", "AI nói trong kỷ nguyên AI tạo sinh bùng nổ, tư duy phản biện (Critical Thinking) và thói quen kiểm chứng nguồn gốc là kỹ năng sinh tồn số quan trọng nhất của mỗi công dân.", "Tra cứu khung năng lực số của UNESCO và Diễn đàn Kinh tế Thế giới (WEF).", "UNESCO Digital Literacy Global Framework, WEF Future of Jobs Report.", "Đúng", "Khi ranh giới giữa hình ảnh thật và giả mạo AI ngày càng mong manh, thói quen chậm lại một nhịp, đặt câu hỏi hoài nghi hợp lý và đối chiếu đa nguồn chính thống là lá chắn bảo vệ tốt nhất trước mọi hình thức thao túng thông tin.")
]

